const terms = []; const keys = []; const errors = [];
for (const it of $input.all()) { const b = it.json.body || {}; if (Array.isArray(b.data)) { terms.push(...b.data); continue; } if (Array.isArray(b.keys)) { for (const k of b.keys) keys.push({ p: b.project_id, k }); continue; } errors.push(it.json.statusCode); }
const reqs = []; const report = [];
const gt = terms.find(x => x.id === 7397484);
if (!gt) report.push({ gl: 'get instant access', status: 'not found' }); else {
  const tr = (gt.translations || []).map(x => ({ langId: x.langId, translation: x.translation || '', description: x.description || '' }));
  const es = tr.find(x => x.langId === 1056);
  if (es && es.translation === 'Obtener acceso inmediato') { es.translation = 'Obtener acceso instant\u00e1neo'; reqs.push({ kind: 'glossary', method: 'PUT', url: A + GLP + '/glossary-terms', body: { terms: [{ id: gt.id, translations: tr }] } }); report.push({ gl: gt.term, status: 'ok' }); }
  else report.push({ gl: gt.term, status: 'ES changed - skipped', live: es ? es.translation : null }); }
for (const j of C.JOBS) {
  const e = keys.find(x => x.p === j.p && Object.values(x.k.key_name || {}).indexOf(j.k) >= 0);
  if (!e) { report.push({ k: j.k, l: j.l, status: 'key not found' }); continue; }
  const t = (e.k.translations || []).find(x => x.language_iso === j.l);
  if (!t) { report.push({ k: j.k, l: j.l, status: 'no translation' }); continue; }
  if (t.translation === j.nw) { report.push({ k: j.k, l: j.l, status: 'already' }); continue; }
  if (t.translation !== j.old) { report.push({ k: j.k, l: j.l, status: 'live changed - skipped', live: t.translation }); continue; }
  if (LING.has(t.modified_by_email)) { report.push({ k: j.k, l: j.l, status: 'linguist edit - skipped', by: t.modified_by_email }); continue; }
  reqs.push({ kind: 'string', k: j.k, l: j.l, want: j.nw, method: 'PUT', url: A + j.p + '/translations/' + t.translation_id, body: { translation: j.nw } });
  report.push({ k: j.k, l: j.l, status: 'ok', old: j.old, nw: j.nw }); }
if (errors.length || terms.length < 600) return [{ json: { none: true, errors, nTerms: terms.length, report } }];
if (!reqs.length) return [{ json: { none: true, report } }];
return reqs.map(r => ({ json: Object.assign({ none: false }, r) }));

const req = $('Prepare').all();
